import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore, type FormEvent } from 'react';
import { requester, RequestError, transport, subscribePackageActivity, getPackageActivity } from './api';
import BrowserPanel from './BrowserPanel';
import Clawd from './Clawd';
import type { ClawdDestination } from './ClawdFlightMenu';
import ClawdPlayroom from './ClawdPlayroom';
import ArchivePanel from './ArchivePanel';
import AgentPanel, { type HandoffContext } from './AgentPanel';
import LaunchPanel from './LaunchPanel';
import LaunchRecords from './LaunchRecords';
import { buildIdentity } from './buildIdentity';
import CleanupPanel from './CleanupPanel';
import WorkPanel from './WorkPanel';
import ComponentPanel from './ComponentPanel';
import { ServiceEvidence } from './ServiceControl';
import RemotePanel, { remoteRequest } from './RemotePanel';
import NetworkPanel from './NetworkPanel';
import DeveloperResources, { ResourceLink, TaskHelp,productTasks } from './Resources';
import PolicyEvidence from './PolicyEvidence';
import PlanReview from './PlanReview';
import ExecutionEvidence from './ExecutionEvidence';
import TaskOutcome from './TaskOutcome';
import CustomPolicy from './CustomPolicy';
import RequestFailure, { asError } from './RequestFailure';
import type { Capability, Draft, Drift, Environment, Inspection, Plan, Receipt } from './types';
import { Brand, Icon, Modal, Notice, Status, WorkspaceActions, WorkspaceActionsContext, formatBytes, formatDate, label, hasConfirmedWorkArchive, type IconName } from './ui';

type Page = 'environments' | 'policy' | 'work' | 'rebuild' | 'history' | 'sessions' | 'agent';
type Tab = 'overview' | 'outbound' | 'state' | 'launch' | 'components';
type Theme = 'light' | 'dark' | 'system';
type Flow = { hostAlias?: string | null; environment: Environment; plan?: Plan; receipt?: Receipt; uncertain?: boolean; initialPassphrase?: string };
const nav: { id: Page; title: string; icon: IconName }[] = [ { id: 'environments', title: '环境', icon: 'environments' }, { id: 'policy', title: '保护方案', icon: 'policy' }, { id: 'work', title: '工作保全', icon: 'environments' }, { id: 'rebuild', title: '清理与重建', icon: 'rebuild' }, { id: 'history', title: '记录与恢复', icon: 'history' }, { id: 'sessions', title: '会话与资料', icon: 'environments' }, { id: 'agent', title: '终端与 Agent', icon: 'terminal' } ];
const defaultDraft: Draft = { preset: 'reduce', keepRemoteControl: false };
function loadDrafts(): Record<string, Draft> { try { return JSON.parse(localStorage.getItem('lintel.drafts') ?? '{}'); } catch { return {}; } }
function errorText(error: unknown) { return error instanceof RequestError ? `${error.message}（${error.code}）` : error instanceof Error ? error.message : '操作未完成，请重新检查本地执行器。'; }

export default function App({ greeting }: { greeting: string }) {
  const [hostAlias, setHostAlias] = useState<string | null>(null);
  const request = useMemo(() => requester(hostAlias), [hostAlias]);
  const packageActivity = useSyncExternalStore(subscribePackageActivity, getPackageActivity);
  const activeHost = useRef(hostAlias); activeHost.current = hostAlias;
  const mainRef = useRef<HTMLElement>(null);
  const [actionsMount, setActionsMount] = useState<HTMLElement | null>(null);
  const [playroom, setPlayroom] = useState<'landscapes' | 'runner' | null>(null);
  const [page, setPage] = useState<Page>('environments');
  const [activeTask,setActiveTask]=useState<string|null>(()=>{const saved=localStorage.getItem('lintel.goal');return productTasks.some(t=>t.id===saved)?saved:null});
  const [tab, setTab] = useState<Tab>('overview');
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [showInspector, setShowInspector] = useState(false);
  const [environments, setEnvironments] = useState<Environment[]>([]);
  const [capabilities, setCapabilities] = useState<Capability[]>([]);
  const [selectedId, setSelectedId] = useState(localStorage.getItem('lintel.selected') ?? '');
  const [inspection, setInspection] = useState<Inspection | null>(null);
  const [jobs, setJobs] = useState<Receipt[]>([]);
  const [drafts, setDrafts] = useState<Record<string, Draft>>(loadDrafts);
  const [busy, setBusy] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | string>('');
  const [notification, setNotification] = useState('');
  const [flow, setFlowState] = useState<Flow | null>(null);
  const [handoff, setHandoff] = useState<HandoffContext | null>(null);
  const [launchTarget, setLaunchTarget] = useState<{environment: Environment; hostAlias: string|null;proxyUrl?:string} | null>(null);
  function setFlow(value: Flow | null | ((old: Flow|null) => Flow|null)) {
    setFlowState(old => { const next = typeof value === 'function' ? value(old) : value; if(!next || next===old)return next;return { ...next, hostAlias: 'hostAlias' in next ? next.hostAlias : hostAlias, environment: {...next.environment} }; });
  }
  function openAgent(context?: Flow) {
    setHandoff({ task: context?.receipt || context?.uncertain ? 'recover_results' : page==='work' || page==='sessions' ? 'preserve_work' : page==='rebuild' ? 'repair_cleanup_retire' : activeTask ?? 'reduce_egress', hostAlias: context ? context.hostAlias ?? null : hostAlias, environment: context?.environment ?? selected, plan: context?.plan, receipt: context?.receipt, uncertain: context?.uncertain, observedAt: new Date().toISOString() });
    setFlow(null); setDialog(null); setPage('agent');
  }
  const [archivePassphrase, setArchivePassphrase] = useState('');
  const [archiveConfirmation, setArchiveConfirmation] = useState('');
  const [dialog, setDialog] = useState<'add' | 'settings' | 'help' | 'support' | 'browser' | 'remote' | 'tasks' | null>(null);
  const [addMode, setAddMode] = useState<'register'|'create'>('create');
  const [name, setName] = useState('');
  const [root, setRoot] = useState('');
  const [formError, setFormError] = useState('');
  const [drift, setDrift] = useState<Drift | null>(null);
  const [archiveJobId, setArchiveJobId] = useState<string | undefined>();
  const [support, setSupport] = useState('');
  const [theme, setTheme] = useState<Theme>((localStorage.getItem('lintel.theme') as Theme) ?? 'system');
  const [queryId, setQueryId] = useState('');
  const [historySearch, setHistorySearch] = useState('');
  const [lastCheck, setLastCheck] = useState<Date | null>(null);
  const [receiptFilter, setReceiptFilter] = useState<'all'|'target'|'attention'>('all');
  const executionLock = useRef(false);
  useEffect(() => { setArchivePassphrase(flow?.receipt ? '' : flow?.initialPassphrase ?? ''); setArchiveConfirmation(flow?.receipt ? '' : flow?.initialPassphrase ?? ''); }, [flow?.plan?.id, flow?.receipt?.id]);
  const activeGoal=productTasks.find(task=>task.id===activeTask);
  useEffect(()=>{if(activeTask)localStorage.setItem('lintel.goal',activeTask);else localStorage.removeItem('lintel.goal')},[activeTask]);
  const selected = environments.find(env => env.id === selectedId);
  const currentHandoff=useMemo<HandoffContext>(()=>({task:activeTask ?? 'recover_results',hostAlias,environment:selected,observedAt:new Date().toISOString()}),[activeTask,hostAlias,selected?.id,selected?.root]);
  const draftKey = hostAlias ? `ssh:${hostAlias}:${selectedId}` : selectedId;
  const draft = drafts[draftKey] ?? defaultDraft;
  const targetJobs = jobs.filter(job => job.environment_id === selectedId);
  const attentionJobs = jobs.filter(job => ['accepted', 'executing', 'verifying', 'pending', 'interrupted', 'needs_reconciliation', 'failed', 'partially_completed'].includes(job.status));
  const visibleJobs = (receiptFilter === 'target' ? targetJobs : receiptFilter === 'attention' ? attentionJobs : jobs).filter(job => `${job.title} ${job.id} ${environments.find(env => env.id === job.environment_id)?.name ?? ''}`.toLowerCase().includes(historySearch.toLowerCase()));

  useEffect(()=>{mainRef.current?.scrollTo({top:0});requestAnimationFrame(()=>{if(document.querySelector('dialog[open]'))return;const heading=mainRef.current?.querySelector<HTMLElement>('h1,h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}})},[page]);
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('lintel.theme', theme); }, [theme]);
  useEffect(() => { localStorage.setItem('lintel.drafts', JSON.stringify(drafts)); }, [drafts]);
  useEffect(() => { localStorage.setItem('lintel.selected', selectedId); }, [selectedId]);
  useEffect(() => { if (!notification) return; const timeout = setTimeout(() => setNotification(''), 6000); return () => clearTimeout(timeout); }, [notification]);

  useEffect(() => {
    if (error && !flow) mainRef.current?.querySelector('.error-wrap')?.scrollIntoView({ block: 'start', behavior: 'instant' });
  }, [error, flow]);

  const refresh = useCallback(async () => {
    const [inventory, history] = await Promise.all([request('discover', {}), request('jobs', {})]);
    if (activeHost.current !== hostAlias) return;
    setEnvironments(inventory.environments); setCapabilities(inventory.capabilities); setJobs(history.jobs);
    setSelectedId(current => inventory.environments.some(env => env.id === current) ? current : inventory.environments[0]?.id ?? '');
    setLastCheck(new Date());
  }, [request, hostAlias]);
  useEffect(() => { let active = true; setLoading(true); setInspection(null); setEnvironments([]); setJobs([]); refresh().catch(error => { if (active) setError(asError(error)); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [refresh]);
  useEffect(() => {
    let active = true; setInspection(null); setDrift(null);
    if (selected) request('inspect', { environment_id: selected.id, trusted_devices: draft.trustedDevices ?? 'unknown' }).then(data => { if (active) setInspection(data); }).catch(error => { if (active) setError(asError(error)); });
    return () => { active = false; };
  }, [selected?.id, selected?.root, lastCheck, request, draft.trustedDevices]);

  async function perform(action: string, work: () => Promise<void>) { const source = hostAlias; setBusy(action); setError(''); try { await work(); } catch (error) { if (activeHost.current === source) setError(asError(error)); } finally { if (activeHost.current === source) setBusy(''); } }
  function updateDraft(value: Partial<Draft>) { setDrafts(current => ({ ...current, [draftKey]: { ...(current[draftKey] ?? defaultDraft), ...value } })); }
  function openClawd(destination: ClawdDestination) { setPlayroom(destination); }
  function closeClawd() { setPlayroom(null); requestAnimationFrame(() => mainRef.current?.querySelector<HTMLButtonElement>('.clawd-pull-trigger')?.focus({ preventScroll: true })); }
  function selectEnvironment(id: string) { setSelectedId(id); setError(''); }
  async function copy(value: string) { try { await navigator.clipboard.writeText(value); setNotification('已复制到剪贴板'); } catch { setError('剪贴板不可用。请在展开的完整文本中选择并复制。'); } }
  const openAdd = (mode: 'register'|'create') => { setAddMode(mode); setFormError(''); setName(''); setRoot(''); setDialog('add'); };
  async function addEnvironment(event: FormEvent) {
    event.preventDefault(); if (!name.trim() || (addMode === 'register' && !root.trim())) return;
    setBusy('add'); setFormError('');
    try { const environment = addMode === 'create' ? await request('create_environment', { name: name.trim() }) : await request('register', { name: name.trim(), root: root.trim() }); await refresh(); setSelectedId(environment.id); setPage('environments'); setDialog(null); setNotification(addMode === 'create' ? '新环境已建立。登录与实际启动仍需单独确认。' : '环境已登记'); }
    catch (error) { setFormError(errorText(error)); } finally { setBusy(''); }
  }
  function preview(_kind: 'policy') {
    if (!selected) return; const target = selected;
    void perform('plan', async () => { const plan = await request('plan_policy', { environment_id: target.id, preset: draft.preset, keep_remote_control: draft.keepRemoteControl, trusted_devices: draft.trustedDevices ?? 'unknown', ...(draft.preset === 'custom' ? { custom_settings: draft.customSettings ?? {} } : { release_settings: draft.keepRemoteControl ? draft.releaseSettings ?? [] : [] }) }); if (activeHost.current === hostAlias) setFlow({ environment: target, plan }); });
  }
  async function executePlan() {
    if (!flow?.plan || executionLock.current || flow.uncertain || flow.receipt) return;
    if (flow.plan.archive_passphrase_required && (archivePassphrase.length < 12 || archivePassphrase !== archiveConfirmation)) return;
    const current = flow; executionLock.current = true; setBusy('execute'); setError('');
    try { const receipt = await requester(current.hostAlias ?? null)('execute', { plan_id: current.plan!.id, approval: current.plan!.hash, ...(current.plan!.archive_passphrase_required ? { archive_passphrase: archivePassphrase } : {}) }); if (activeHost.current !== hostAlias) return; setFlow(value => value === current ? { ...current, receipt, initialPassphrase: undefined } : value); await refresh(); }
    catch (error) { if (activeHost.current === hostAlias) { setFlow(value => value === current ? { ...current, uncertain: true } : value); setError(asError(error)); } }
    finally { executionLock.current = false; if (activeHost.current === hostAlias) setBusy(''); }
  }
  function reconcile() {
    if (!flow?.plan) return; const source = flow;
    void perform('reconcile', async () => { const found = source.hostAlias ? await remoteRequest<Receipt>({op:'reconnect',alias:source.hostAlias,plan_id:source.plan!.id}) : await requester(null)('job', { job_id: source.plan!.id }); if (activeHost.current !== hostAlias) return; setFlow(value => value === source ? { ...source, receipt: found, uncertain: false, initialPassphrase: undefined } : value); await refresh(); });
  }
  function refreshReceipt() { if (!flow?.receipt) return; const source = flow; void perform('query', async () => { const receipt = source.hostAlias ? await remoteRequest<Receipt>({ op:'reconnect', alias:source.hostAlias, plan_id:source.receipt!.plan_id }) : await requester(null)('job', { job_id: source.receipt!.id }); if (activeHost.current !== hostAlias) return; setFlow(value => value === source ? { ...source, receipt, initialPassphrase: undefined } : value); await refresh(); }); }
  function restore(receipt: Receipt) {
    const source = flow; const target = environments.find(env => env.id === receipt.environment_id);
    if (!target) { setError('原环境不在当前清单中，无法准备恢复。请重新检查环境。'); return; }
    void perform('restore', async () => { const plan = await request('plan_restore', { job_id: receipt.id }); if (activeHost.current === hostAlias) setFlow(value => value === source ? { environment: target, plan } : value); });
  }
  function resumeService(receipt: Receipt) {
    const source = flow; const target = environments.find(env => env.id === receipt.environment_id);
    if (!target) { setError('原环境不在当前清单中，无法准备服务恢复。请刷新环境后再查看。'); return; }
    void perform('restore-service', async () => { const plan = await request('plan_service_resume', { job_id: receipt.id }); if (activeHost.current === hostAlias) setFlow(value => value === source ? { environment: target, plan } : value); });
  }
  function launch(environment: Environment, sourceHost=hostAlias,proxyUrl?:string) { setLaunchTarget({ environment: {...environment}, hostAlias: sourceHost,proxyUrl }); }
  function checkDrift() { if (selected) void perform('drift', async () => { setDrift(await request('drift', { environment_id: selected.id })); }); }
  function downloadSupport() { const url = URL.createObjectURL(new Blob([support], { type: 'application/json' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'lintel-support-redacted.json'; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); setNotification('已请求保存脱敏资料。请核对文件后再分享。'); }
  function queryOriginalJob() { void perform('query', async () => { const receipt = await request('job', { job_id: queryId.trim() }); if (activeHost.current !== hostAlias) return; const target = environments.find(env => env.id === receipt.environment_id); if (!target) throw new Error('任务存在，但对应环境不在当前清单。请刷新环境后再查看。'); setFlow({ environment: target, receipt }); }); }
  function supportPreview() { void perform('support', async () => { setSupport(JSON.stringify(await request('export_support', {}), null, 2)); setDialog('support'); }); }
  function Path({ value }: { value: string }) { return <div className="path"><code title={value}>{value}</code><button className="icon-button" aria-label="复制完整路径" onClick={() => void copy(value)}><Icon name="copy" size={14}/></button></div>; }
  function Warnings({ items }: { items: string[] }) { return <>{items.length > 0 && <Notice tone="warning"><ul className="compact-list">{items.map((item, index) => <li key={index}>{item}</li>)}</ul></Notice>}</>; }

  function continueGoal() {
    const destinations: Record<string, () => void> = {
      reduce_egress: () => setPage('policy'), preserve_work: () => setPage('work'),
      repair_cleanup_retire: () => setPage('rebuild'), recover_results: () => setPage('history'),
      browser_profile: () => setDialog('browser'), ssh_remote: () => setDialog('remote'),
    };
    if (activeTask) destinations[activeTask]?.();
  }
  return <WorkspaceActionsContext.Provider value={actionsMount}><div className={`app-shell ${sidebarCollapsed ? 'sidebar-collapsed' : ''}`}>
    <aside className="sidebar">
      <div className="brand"><strong>lintel<span className="brand-cursor">_</span></strong><button className="icon-button" aria-label={sidebarCollapsed ? '展开侧栏' : '收起侧栏'} onClick={() => setSidebarCollapsed(value => !value)}><Icon name="sidebar" size={18}/></button></div>
      <button className="new-space" onClick={() => openAdd('create')}><span><Icon name="plus" size={15}/></span><span>新建环境</span></button>
      <nav aria-label="主导航">{nav.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} title={item.title} aria-current={page === item.id ? 'page' : undefined} onClick={() => {setPage(item.id);const task=({policy:'reduce_egress',work:'preserve_work',rebuild:'repair_cleanup_retire',history:'recover_results',sessions:'preserve_work'} as Partial<Record<Page,string>>)[item.id];if(task)setActiveTask(task);}}><Icon name={item.icon}/><span>{item.title}</span></button>)}</nav>
      <div className="sidebar-environments"><div className="nav-caption">你的环境<button className="icon-button" aria-label="添加现有环境" onClick={() => openAdd('register')}><Icon name="plus" size={13}/></button></div>{environments.map(env => <button key={env.id} className={`sidebar-environment ${env.id === selectedId ? 'chosen' : ''}`} onClick={() => { selectEnvironment(env.id); setPage('environments'); }} title={env.name}>{env.name.replace('Claude Code · ', '')}</button>)}</div>
      <div className="sidebar-bottom"><button className="nav-item" onClick={() => setDialog('help')} title="帮助"><Icon name="help"/><span>帮助</span></button><button className="profile-settings" onClick={() => setDialog('settings')} title="设置与模块"><span className="profile-symbol">L</span><span><strong>本地工作空间</strong><small>Lintel · 开发候选</small></span><Icon name="chevron" size={14}/></button></div>
    </aside>
    <div className="workspace">
      <header className={`target-bar ${page === 'environments' ? 'home-target' : ''}`}><div className="target-icon"><Icon name="environments" size={19}/></div><div className="target-context"><span className="eyebrow">当前操作目标</span>{<div className="target-line"><button className="host-switch" disabled={!!busy} onClick={() => setDialog('remote')}>{hostAlias ?? '本机'}<Icon name="chevron" size={11}/></button><span className="slash">/</span><select aria-label="当前环境" disabled={!!busy} value={selectedId} onChange={event => selectEnvironment(event.target.value)}>{!environments.length && <option value="">尚未选择环境</option>}{environments.map(env => <option key={env.id} value={env.id}>{env.name}</option>)}</select></div>}{selected && <code className="target-root" title={selected.root}>{selected.root}</code>}</div><ThemeSwitch theme={theme} onChange={setTheme}/><span className="connection"><span className="status-dot"/>{transport === 'native' ? '本地执行器' : transport === 'synthetic' ? '合成测试执行器' : '桌面连接不可用'}</span><button className="icon-button refresh-button" aria-label="重新检查环境" disabled={!!busy || loading} onClick={() => void perform('refresh', refresh)}><Icon name="refresh"/></button></header>
      {hostAlias && <div className="remote-banner"><Icon name="terminal" size={13}/>远程工作空间 · {hostAlias}<span>环境、计划与记录均来自这台主机</span></div>}{transport === 'synthetic' && <div className="fixture-banner"><Icon name="terminal" size={15}/><span>测试空间 · 操作仅作用于合成数据</span></div>}
      {packageActivity.length>0 && <aside className="package-activity" role="status" aria-live="polite" aria-label="工作包读取状态">{packageActivity.map(item=><div key={item.id}><strong>{item.hostAlias?`SSH · ${item.hostAlias}`:'本机'} · {item.running?`正在${item.label}`:`等待当前操作结束后${item.label}`}</strong><span>每次读取都会完整核验工作包，较大资料可能需要较长时间。离开页面会清除页面中的口令与正文，已提交的读取仍会继续。{item.waiting>0?` 同一队列中还有 ${item.waiting} 个请求等待这次操作结束。`:''}</span></div>)}</aside>}
      <main ref={mainRef} className={`main-content ${page === 'environments' ? 'home-content' : page === 'sessions' ? 'reading-content' : ''}`} id="main-content">
        {activeGoal && page!=='environments' && <aside className="current-goal" aria-label="当前任务目标"><div><span className="eyebrow">现在要完成</span><strong>{activeGoal.label}</strong><details><summary>任务范围与后续</summary><p>{activeGoal.summary}</p></details></div><button className="text-button" onClick={()=>setPage('environments')}>选择其他任务 →</button></aside>}
        {error && !flow && <div className="error-wrap"><RequestFailure error={error}/><button className="text-button" onClick={() => setError('')}>收起</button></div>}
        {loading ? <div className="empty-state"><span className="loading-mark"/><h2>正在检查本地环境</h2><p>只读取已知目录与安装信息，不启动 Claude。</p></div> : transport === 'unavailable' ? <div className="empty-state"><Brand/><h1>从桌面应用开始</h1><p>此浏览器页面没有本机执行权限。<br/>开发预览请显式运行 <code>npm run dev:synthetic</code>。</p><button onClick={() => setDialog('help')}>查看使用说明</button></div> : <>
          {page === 'environments' && <>
            <section className="home-stage"><div className="home-greeting"><Clawd interactive scrollRef={mainRef} onChoose={openClawd}/><div><h1 className="home-title">{greeting}</h1><p>你的工作空间，慢慢整理就好。</p></div></div>
            <section className="home-composer" aria-label="开始或继续工作"><button className="home-task-prompt" onClick={() => setDialog('tasks')}>给这个环境，做一点小小的整理。<span>选择眼前的事，从预览开始。</span></button><div className="home-composer-footer"><button className="text-button" onClick={() => openAdd('register')}><Icon name="plus" size={15}/>添加现有环境</button><button className="primary" onClick={() => setDialog('tasks')}>开始一项任务<Icon name="arrow" size={16}/></button></div></section>
            {activeGoal && <button className="home-continue" onClick={continueGoal}><span>继续上次的目标</span><strong>{activeGoal.label}</strong><Icon name="arrow" size={14}/></button>}
            {attentionJobs.length > 0 && <button className="home-pending" onClick={() => {setReceiptFilter('attention');setPage('history');}}><Icon name="history" size={14}/>{attentionJobs.length} 份任务需要核对<Icon name="arrow" size={14}/></button>}
            {environments.length === 0 ? <p className="home-empty-note">还没有环境也没关系。可以先建立专用环境，或从浏览器、SSH 与 CLI 开始。</p> : <>
              {selected?.status === 'retired' && <Notice>此环境已退役，保留原工作目录。<button className="text-button" disabled={!!busy} onClick={() => void perform('reactivate', async () => { await request('reactivate_environment', { environment_id: selected.id }); await refresh(); setNotification('已重新启用环境；不会恢复已删除凭据。'); })}>重新启用环境</button></Notice>}              {selected && <div className="home-tools"><div className="home-work-links"><button onClick={() => setDialog('browser')}>浏览器</button><button onClick={() => { setArchiveJobId(undefined); setPage('sessions'); }}>会话与资料</button><button onClick={() => openAgent()}>交给 Agent<Icon name="arrow" size={14}/></button></div><button className="inspector-toggle" aria-expanded={showInspector} onClick={() => setShowInspector(value => !value)}>环境详情<Icon name="chevron" size={13}/></button></div>}
              {selected && showInspector && <section className="detail-panel"><div className="inspector-status"><span>{lastCheck ? `${lastCheck.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })} 已检查` : '尚未检查'}</span><button className="text-button" disabled={!!busy} onClick={() => void perform('refresh', refresh)}><Icon name="refresh" size={13}/>重新检查</button></div><div className="tabs" role="tablist" aria-label="环境详情" onKeyDown={event => { const ids: Tab[] = ['overview','outbound','state','launch','components']; let next = ids.indexOf(tab); if (event.key === 'ArrowRight') next = (next + 1) % ids.length; else if (event.key === 'ArrowLeft') next = (next + ids.length - 1) % ids.length; else if (event.key === 'Home') next = 0; else if (event.key === 'End') next = ids.length - 1; else return; event.preventDefault(); setTab(ids[next]); (event.currentTarget.querySelectorAll('button')[next] as HTMLButtonElement).focus(); }}>{([['overview','概况'],['outbound','外发与权限'],['state','本地状态'],['launch','启动与来源'],['components','关联组件']] as const).map(([id,title]) => <button role="tab" tabIndex={tab === id ? 0 : -1} aria-selected={tab === id} aria-controls="environment-tab-content" key={id} onClick={() => setTab(id)}>{title}</button>)}</div><div className="detail-body" id="environment-tab-content" role="tabpanel">
                {tab === 'components' ? <ComponentPanel key={JSON.stringify([hostAlias,selected.id])} send={request} environment={selected} onEntry={entry=>{if(entry==='browser')setDialog('browser');else if(entry==='launch')launch(selected);else if(entry==='policy')setPage('policy');else if(entry==='cleanup'||entry==='service')setPage('rebuild');}} onJob={id=>void perform('query',async()=>{const receipt=await request('job',{job_id:id});if(activeHost.current!==hostAlias)return;setFlow({hostAlias,environment:selected,receipt});})}/> : !inspection ? <p className="muted">正在读取此环境…</p> : <>
                  {tab === 'overview' && <><div className="overview-grid"><button className="overview-item" onClick={() => setPage('policy')}><span className="feature-icon blue"><Icon name="policy" size={20}/></span><span><strong>外发控制</strong><small>{inspection.settings.filter(setting => setting.status === 'configured').length} / {inspection.settings.length} 项已设置关闭</small></span><Icon name="chevron" size={14}/></button><button className="overview-item" onClick={() => setTab('state')}><span className="feature-icon violet"><Icon name="environments" size={20}/></span><span><strong>工作内容</strong><small>{inspection.assets.filter(asset => ['instructions','memory','sessions'].includes(asset.category)).reduce((sum,asset) => sum + asset.count,0)} 项可识别资料</small></span><Icon name="chevron" size={14}/></button><button className="overview-item" onClick={() => setPage('history')}><span className="feature-icon amber"><Icon name="history" size={20}/></span><span><strong>变更记录</strong><small>{targetJobs.length ? `${targetJobs.length} 次任务 · 查看结果` : '还没有执行过任务'}</small></span><Icon name="chevron" size={14}/></button></div><details className="environment-diagnostics"><summary><span><Icon name="help" size={15}/>配置来源与验证范围</span><Icon name="chevron" size={14}/></summary><div className="fact-row"><span>配置目录</span><Path value={selected.root}/></div><div className="fact-row"><span>验证范围</span><span>已读取配置；实际启动与网络约束需分别验证</span></div><Warnings items={inspection.warnings}/></details></>}
                  {tab === 'outbound' && <><SettingsRows settings={inspection.settings}/>{hostAlias ? <Notice>这台主机的网络通道需要使用远端 runner 操作。桌面的本机代理不会自动覆盖 SSH 主机。</Notice> : <NetworkPanel key={selected.id} environmentId={selected.id} executable={!!selected.executable} onLaunch={proxy=>launch(selected,null,proxy)}/>} <div className="separated"><h3>浏览器权限</h3><p className="muted">在设置与模块中连接具体浏览器 profile。网络配置、连接观察和强约束是独立能力。</p><button className="text-button" onClick={() => setDialog('browser')}>管理浏览器 profile<Icon name="arrow" size={14}/></button></div></>}
                  {tab === 'state' && <><div className="asset-grid">{inspection.assets.map(asset => <div className="asset-row" key={asset.category}><span>{categoryLabel(asset.category)}</span><strong>{asset.count} 项</strong><span className="muted">{formatBytes(asset.bytes)}</span></div>)}</div>{inspection.assets.some(asset => asset.complete === false) && <Notice tone="warning">统计只覆盖已扫描部分（目录过大或包含未解析链接）；归档预览会单独执行完整核对并报告其准入结果。</Notice>}<Notice>数量来自可识别文件的元数据，不代表凭据已隔离或旧状态已清理。</Notice><button className="text-button section-action" onClick={() => setPage('work')}>选择保留内容并准备保全<Icon name="arrow" size={15}/></button></>}
                  {tab === 'launch' && <><div className="fact-row"><span>启动程序</span>{selected.executable ? <Path value={selected.executable}/> : <span>尚未定位；不会擅自安装 Claude</span>}</div><div className="fact-row"><span>配置根</span><Path value={selected.root}/></div><div className="fact-row"><span>已有会话</span><span>不会自动退出或重启</span></div><Notice>新启动使用此环境的准确程序与配置根。其他终端、IDE 与服务入口的生效状态需独立确认。</Notice><div className="button-row"><button className="primary" disabled={!!busy || !selected.executable || selected.status === 'retired'} onClick={() => launch(selected)}>打开 Claude<Icon name="arrow" size={15}/></button>{hostAlias && <span className="muted">在 Terminal 连接此主机</span>}</div></>}
                </>}
              </div></section>}
              {selected && showInspector && <div className="drift-block"><div><h3>上次之后，有什么变化？</h3><p>检查已管理的设置，由你决定是否接受。</p></div><button disabled={!!busy} onClick={checkDrift}><Icon name="refresh" size={15}/>检查变化</button>{drift && <div className="drift-result"><Status value={drift.status}/>{drift.changes.length > 0 ? <><SettingsRows settings={drift.changes}/><div className="button-row"><button onClick={() => setPage('policy')}>重新应用方案</button><button disabled={!!busy} onClick={() => void perform('accept', async () => { await request('accept_drift', { environment_id: selected.id }); setDrift(await request('drift', { environment_id: selected.id })); setNotification('已将当前值记为此环境的基线'); })}>接受当前值</button></div></> : <span>当前检查范围内没有待处理差异。</span>}</div>}</div>}
            </>}
            </section>
          </>}
          {page === 'policy' && <>
            <div className="page-heading"><div><span className="eyebrow">01 / make it yours</span><h1>保护方案</h1><p>选好需要保留的功能，修改先留在当前环境的草案里。</p></div><Clawd small mood="plan"/></div>
            {!selected ? <SelectTarget onAdd={() => openAdd('register')}/> : <>
              <fieldset className="preset-grid"><legend className="sr-only">保护方案</legend><label className={`preset ${draft.preset === 'preserve' ? 'chosen' : ''}`}><input type="radio" name="preset" value="preserve" checked={draft.preset === 'preserve'} onChange={() => updateDraft({ preset: 'preserve', releaseSettings: [] })}/><span className="preset-copy"><strong>保持功能</strong><span>关闭错误回报与反馈调查。<br/>保留指标和主动反馈的当前设置。</span></span></label><label className={`preset ${draft.preset === 'reduce' ? 'chosen' : ''}`}><input type="radio" name="preset" value="reduce" checked={draft.preset === 'reduce'} onChange={() => updateDraft({ preset: 'reduce', releaseSettings: [] })}/><span className="preset-copy"><strong>减少外发</strong><span>分别控制产品指标、错误回报、<br/>主动反馈与调查。</span></span></label><label className={`preset ${draft.preset === 'custom' ? 'chosen' : ''} ${!inspection?.policy?.supported_presets?.includes('custom') ? 'unavailable' : ''}`}><input type="radio" name="preset" value="custom" checked={draft.preset === 'custom'} disabled={!inspection?.policy?.supported_presets?.includes('custom')} onChange={() => updateDraft({ preset: 'custom', releaseSettings: [] })}/><span className="preset-copy"><strong>自定义</strong><span>逐项决定，保留其余原值。<br/>每个选择都先预览再执行。</span></span></label></fieldset>
              {draft.preset === 'custom' && inspection?.policy?.supported_presets?.includes('custom') && <CustomPolicy policy={inspection.policy} settings={inspection.settings} choices={draft.customSettings ?? {}} onChange={customSettings => updateDraft({ customSettings })}/>}
              {inspection && !inspection.policy?.supported_presets?.includes('custom') && <Notice tone="warning">当前执行器尚不支持自定义方案。请更新本机 App 或此 SSH alias 的 runner 后重新检查；已有草案会保留。</Notice>}
              <section className="surface"><div className="surface-heading"><h2>保留你需要的能力</h2><span className="small-label">仅当前环境</span></div><label className="checkbox-row"><span><strong>保留 Remote Control</strong><span>按已识别版本和组织条件计算结果。已有关闭值会显示冲突；自定义选择不会被此选项自动改写。需在预览中核对预计条件。</span></span><input type="checkbox" aria-label="保留 Remote Control" checked={draft.keepRemoteControl} onChange={event => updateDraft({ keepRemoteControl: event.target.checked, releaseSettings: [] })}/></label><label className="policy-condition"><span>组织是否要求 Trusted Devices？</span><select aria-label="Trusted Devices 组织条件" value={draft.trustedDevices ?? 'unknown'} onChange={event => updateDraft({ trustedDevices: event.target.value as NonNullable<Draft['trustedDevices']>, releaseSettings: [] })}><option value="unknown">尚未确认</option><option value="required">要求</option><option value="not_required">已确认不要求</option></select><small>只记录你的声明，不查询组织或账号。</small></label>{inspection?.policy && <PolicyEvidence policy={inspection.policy}/>}{draft.keepRemoteControl && draft.preset !== 'custom' && inspection?.policy?.remote_control.blockers.map(blocker => <label className="checkbox-row policy-release" key={blocker.key}><span><strong>允许在预览中解除 <code>{blocker.key}</code></strong><span>当前值 {JSON.stringify(blocker.value)} · {blocker.reason}。仅删除本环境 user settings 的该字段；会重新开放对应流量。</span></span><input type="checkbox" aria-label={`允许解除 ${blocker.key}`} checked={(draft.releaseSettings ?? []).includes(blocker.key)} onChange={event => updateDraft({ releaseSettings: event.target.checked ? [...draft.releaseSettings ?? [], blocker.key] : (draft.releaseSettings ?? []).filter(key => key !== blocker.key) })}/></label>)}{inspection && !inspection.policy && <Notice tone="warning">当前执行器未提供版本化策略结果；请更新对应 runner 后重新预览。</Notice>}<div className="preserve-note"><Icon name="check" size={16}/><span>官方更新、WebFetch 安全预检查、用户 OTel 与通用代理保持原样。</span></div></section>
              <section className="surface"><div className="surface-heading"><h2>当前配置</h2><span className="small-label">读回值 ≠ 实际运行证明</span></div>{inspection ? <SettingsRows settings={inspection.settings}/> : <p className="padded muted">正在读取设置…</p>}</section>
              <Notice>配置将在 core 生成的计划中确定。当前打开的 Claude 会话不会被自动退出，生效时机以每项结果为准。</Notice>
              <WorkspaceActions><div><strong>草案已保留</strong><span>仅作用于 {selected.name}</span></div><button className="primary" disabled={!!busy || !inspection || (draft.preset === 'custom' && !inspection.policy?.supported_presets?.includes('custom'))} onClick={() => preview('policy')}>{busy === 'plan' ? '正在生成计划…' : '预览变更'}<Icon name="arrow" size={16}/></button></WorkspaceActions>
            </>}
          </>}
          {page === 'work' && (selected ? <WorkPanel key={`${hostAlias ?? 'local'}:${selected.id}`} send={request} hostAlias={hostAlias} environment={selected} inspection={inspection} onPlan={plan=>{if(activeHost.current===hostAlias)setFlow({environment:selected,hostAlias,plan});}} onArchives={()=>{setArchiveJobId(undefined);setPage('sessions');}}/> : <SelectTarget onAdd={() => openAdd('register')}/>)}
          {page === 'rebuild' && (selected ? <CleanupPanel key={`${hostAlias ?? 'local'}-${selected.id}`} send={request} hostAlias={hostAlias} environment={selected} refreshKey={lastCheck?.getTime()} onPlan={plan => { if (activeHost.current === hostAlias) setFlow({environment:selected,plan}); }} onBrowser={() => setDialog('browser')} onWork={() => setPage('work')}/> : <SelectTarget onAdd={() => openAdd('register')}/>)}
          {page === 'sessions' && <><div className="page-heading"><div><span className="eyebrow">work / read, select, continue</span><h1>会话与资料</h1><p>原件完整保留；选择需要的内容，在准确项目里继续。</p></div><Clawd small mood="pack"/></div><ArchivePanel key={hostAlias ?? 'local'} send={request} jobs={jobs} environments={environments} initialJob={archiveJobId} selectedId={selectedId} hostAlias={hostAlias} onImport={(environment,plan,passphrase)=>setFlow({environment,plan,initialPassphrase:passphrase})}/></>}
          {page === 'agent' && <AgentPanel context={handoff ?? currentHandoff}/>}
          {page === 'history' && <>
            <div className="page-heading"><div><span className="eyebrow">03 / nothing lost in the shuffle</span><h1>每一步，都有记录</h1><p>查看真实执行结果；可恢复的配置会先检查后续编辑。</p></div><button disabled={!!busy} onClick={() => void perform('refresh', refresh)}><Icon name="refresh" size={16}/>刷新</button></div>
            <div className="history-toolbar"><div className="segmented"><button aria-pressed={receiptFilter === 'all'} onClick={() => setReceiptFilter('all')}>全部环境</button><button aria-pressed={receiptFilter === 'target'} onClick={() => setReceiptFilter('target')}>当前环境</button><button aria-pressed={receiptFilter === 'attention'} onClick={() => setReceiptFilter('attention')}>待处理{attentionJobs.length > 0 && <span className="filter-count">{attentionJobs.length}</span>}</button></div><label className="history-search"><span className="sr-only">搜索任务记录</span><input type="search" value={historySearch} onChange={event => setHistorySearch(event.target.value)} placeholder="搜索记录、环境或任务 ID"/></label></div><details className="query-task"><summary>执行连接中断？用原任务 ID 找回结果</summary><form onSubmit={event => { event.preventDefault(); queryOriginalJob(); }}><label className="field">原任务 ID<input value={queryId} onChange={event => setQueryId(event.target.value)} placeholder="粘贴计划或任务 ID" spellCheck={false}/></label><button disabled={!!busy || !queryId.trim()}>查询原任务</button></form><p className="small-print">只查询已有结果，不会重新执行。</p></details>
            {visibleJobs.length === 0 ? <div className="empty-state bordered"><Clawd mood="rest"/><h2>{historySearch ? '没有匹配的记录' : receiptFilter === 'attention' ? '目前没有待处理的任务' : '还没有执行记录'}</h2><p>{receiptFilter === 'attention' ? '执行中、中断和未完成的任务会集中在这里。' : '应用一份方案后，这里会保留每一步的结果与恢复入口。'}</p>{receiptFilter === 'attention' ? <button onClick={() => setReceiptFilter('all')}>查看全部记录</button> : <button onClick={() => setPage('policy')}>选择保护方案</button>}</div> : <div className="job-list">{visibleJobs.map(job => { const env = environments.find(item => item.id === job.environment_id); return <div className="job-row" key={job.id}><span className="job-icon"><Icon name="history" size={19}/></span><div className="job-copy"><strong>{job.title}</strong><span>{env?.name ?? job.environment_id} · {formatDate(job.created_at)}</span><code>{job.id}</code></div><Status value={job.status}/><button disabled={!!busy} onClick={() => { if (env) void perform('query', async () => { const receipt = await request('job', { job_id: job.id }); if (activeHost.current !== hostAlias) return; setFlow({ environment: env, receipt }); }); else setError('未找到该记录对应的环境，请重新检查环境清单。'); }}>查看结果</button></div>; })}</div>}
            <LaunchRecords send={request} hostAlias={hostAlias} onHandoff={record=>{setHandoff({task:"recover_results",hostAlias,launch:record,environment:environments.find(e=>e.root===(record.root ?? record.config_root)),observedAt:new Date().toISOString()});setPage("agent");}}/><div className="inline-route"><ResourceLink resource="recovery-guide">中断、错误与恢复指南</ResourceLink></div><div className="archive-shortcut"><Clawd small mood="pack"/><div><h3>工作归档</h3><p>查看加密归档中的文件，或选择迁入另一环境。</p></div><button onClick={() => { setArchiveJobId(undefined); setPage('sessions'); }}>查看归档<Icon name="arrow" size={14}/></button></div><div className="support-footer"><span>需要排查问题？先预览脱敏后的支持资料。</span><button className="text-button" disabled={!!busy} onClick={supportPreview}>预览支持资料<Icon name="arrow" size={15}/></button></div>
          </>}
        </>}
      </main>
      <footer className="workspace-actions" aria-label="当前页面操作" ref={setActionsMount}/>
    </div>
    {notification && <div className="toast" role="status"><Icon name="check" size={17}/>{notification}<button className="icon-button" aria-label="关闭提示" onClick={() => setNotification('')}><Icon name="close" size={14}/></button></div>}
    {dialog === 'tasks' && <Modal title="开始一项任务" wide onClose={() => setDialog(null)}><div className="modal-body task-home"><TaskHelp onChooseTask={id => {setActiveTask(id);setDialog(null);}} onProtect={() => setPage('policy')} onWork={() => setPage('work')} onCleanup={() => setPage('rebuild')} onBrowser={() => setDialog('browser')} onRemote={() => setDialog('remote')} onRecovery={() => {setReceiptFilter('attention');setPage('history');}}/></div><div className="modal-footer"><button onClick={() => setDialog(null)}>先待一会儿</button></div></Modal>}
    {dialog === 'add' && <Modal title={addMode === 'create' ? '建立专用环境' : '添加现有环境'} onClose={() => { if (!busy) setDialog(null); }}><form onSubmit={addEnvironment}><div className="modal-body"><div className="segmented add-tabs"><button type="button" aria-pressed={addMode === 'create'} onClick={() => setAddMode('create')}>建立新环境</button><button type="button" aria-pressed={addMode === 'register'} onClick={() => setAddMode('register')}>登记已有目录</button></div><p>{addMode === 'create' ? 'Lintel 会建立新的配置根，不复制现有登录、凭据或执行配置。' : '添加明确的 Claude Code 配置目录。登记不会改变目录中的设置。'}</p><label className="field">环境名称<input required maxLength={100} value={name} onChange={event => setName(event.target.value)} placeholder="例如：写作环境"/></label>{addMode === 'register' && <label className="field">配置目录完整路径<input required value={root} onChange={event => setRoot(event.target.value)} placeholder="/path/to/claude-config" spellCheck={false}/><small>这是配置根，不是项目代码目录。</small></label>}{formError && <div role="alert"><Notice tone="error">{formError}</Notice></div>}</div><div className="modal-footer"><button type="button" disabled={!!busy} onClick={() => setDialog(null)}>取消</button><button className="primary" disabled={!!busy || !name.trim() || (addMode === 'register' && !root.trim())} type="submit">{busy === 'add' ? '正在处理…' : addMode === 'create' ? '建立环境' : '添加环境'}</button></div></form></Modal>}
    {playroom && <Modal title="Clawd 的小小世界" wide onClose={closeClawd}><div className="modal-body playroom-body"><ClawdPlayroom initialTab={playroom}/></div></Modal>}
    {dialog === 'remote' && <Modal title="主机与 SSH 连接" wide onClose={() => setDialog(null)}><div className="modal-body"><RemotePanel current={hostAlias} onOpenLaunch={(alias,record)=>{setHandoff({task:"recover_results",hostAlias:alias,launch:record,observedAt:new Date().toISOString()});setDialog(null);setPage("agent");}} onRemoved={alias => { if (hostAlias === alias) { activeHost.current = null; setHostAlias(null); setSelectedId(''); setFlow(null); setError(''); setPage('environments'); } }} onOpenReceipt={(alias, receipt, environment) => { activeHost.current = alias; setHostAlias(alias); setSelectedId(environment.id); setDialog(null); setFlow({ hostAlias: alias, environment, receipt }); setError(''); setBusy(''); setPage('history'); }} onSelect={alias => { activeHost.current = alias; setHostAlias(alias); setSelectedId(''); setDialog(null); setFlow(null); setError(''); setBusy(''); setPage('environments'); }}/></div><div className="modal-footer"><button onClick={() => setDialog(null)}>完成</button></div></Modal>}
    {dialog === 'browser' && <Modal title="浏览器工作空间" wide onClose={() => setDialog(null)}><div className="modal-body"><BrowserPanel/></div><div className="modal-footer"><button onClick={() => setDialog(null)}>完成</button></div></Modal>}
    {dialog === 'settings' && <Modal title="设置与模块" wide onClose={() => setDialog(null)}><div className="modal-body"><h3>外观</h3><ThemeSwitch theme={theme} onChange={setTheme}/><p className="small-print">Day 是暖纸色，Night 是安静的深色；System 随设备外观变化。</p><button className="section-action" onClick={() => setDialog('remote')}>主机与 SSH 连接<Icon name="arrow" size={14}/></button><h3 className="separated">当前模块能力</h3><p className="muted">以下状态来自当前主机的执行器。模块实现与桌面接入、安装验证分别记录。</p><div className="capability-list">{capabilities.map(capability => <div className="capability" key={capability.name}><div><strong>{label(capability.name)}</strong><p>{capability.reason}</p></div><Status value={capability.status}/></div>)}</div><button className="section-action" onClick={() => setDialog('browser')}>浏览器配对、清理与权限<Icon name="arrow" size={15}/></button><Notice>受控通道位于环境的“外发与权限”。远程任务可在顶部主机入口中连接。后台漂移检查、菜单栏与自动更新也未启用；请使用主界面主动检查。</Notice><div className="fact-row"><span>数据与隐私</span><span>本地处理，无默认分析上传或远程字体。</span></div></div><div className="modal-footer"><button onClick={() => setDialog(null)}>完成</button></div></Modal>}
    {dialog === 'help' && <Modal title="使用 Lintel" wide onClose={() => setDialog(null)}><div className="modal-body help-content"><div className="help-brand"><Brand/><div><h3>清楚知道改了什么</h3><p>Lintel 管理具体的 Claude 使用环境。</p></div></div><TaskHelp onChooseTask={setActiveTask} onProtect={() => {setDialog(null);setPage('policy');}} onWork={() => {setDialog(null);setPage('work');}} onCleanup={() => {setDialog(null);setPage('rebuild');}} onBrowser={() => setDialog('browser')} onRemote={() => setDialog('remote')} onRecovery={() => {setDialog(null);setPage('history');}}/><section className="offline-help separated"><h3>从目标到结果，四个明确步骤</h3><ol><li><strong>核对目标。</strong>确认主机、环境名称与完整配置 root；启动还要选择项目 cwd。浏览器操作始终属于这台 Mac 的具体 profile。</li><li><strong>准备并审阅。</strong>草案不会直接执行。计划列出实际落点、文件用途、启用选择和影响；目标或稿件改变后重新预览。</li><li><strong>批准当前计划。</strong>工作保全先加密归档，再准备新环境和迁入；旧登录保留。清理另需停写入者，官方注销也要明确选择。</li><li><strong>按原 ID 继续。</strong>已接收、完成和覆盖范围分别查看。断线或回复丢失时查询原任务；恢复配置或服务各自生成新预览。</li></ol><h4>带着旧工作继续</h4><p>“会话与资料”按页阅读包中原件；未知记录保留，不透明 thinking 不进入交接稿。选片段、编辑审阅后可复制并打开新会话，再由你粘贴发送；App 不宣称模型已接收。原生续聊单独检查支持条件，用私有运行副本，保留归档原件。</p><h4>交给 CLI／Agent</h4><p>输入实际 CLI 完整路径，核对平台、协议、用户与同一份 state，再审阅操作交接包。原任务只给出准确查询入口；口令与工作正文不进入该包，复制不会授权新执行。没有 CLI 时按外链说明取得候选或从源码构建。</p></section><Notice>新目录不等于旧登录已退出，配置值不等于强网络约束。尚未交付的完整产品能力见“设置与模块”。</Notice><h3>遇到错误</h3><p>计划生成后目标发生变化时，重新生成预览。执行结果不确定时查询原任务，不再次提交清理。支持资料可在“记录与恢复”本地预览，不会自动上传。</p><div className="inline-route"><button className="text-button" onClick={() => openAgent()}>终端与 Agent →</button></div><p className="help-revision">本地帮助 · Lintel {buildIdentity.version} · docs revision {buildIdentity.docs_revision}{buildIdentity.source_dirty ? "（开发构建）" : ""}</p><DeveloperResources/></div><div className="modal-footer"><button onClick={() => setDialog('settings')}>查看模块能力</button><button className="primary" onClick={() => setDialog(null)}>知道了</button></div></Modal>}
    {dialog === 'support' && <Modal title="脱敏支持资料" wide onClose={() => setDialog(null)}><div className="modal-body"><Notice>请先检查内容，再自行分享。不会自动上传；不应包含令牌、Cookie 或会话正文。</Notice><textarea className="support-preview" aria-label="脱敏支持资料内容" value={support} readOnly spellCheck={false}/></div><div className="modal-footer"><button onClick={() => setDialog(null)}>关闭</button><button onClick={downloadSupport}><Icon name="download" size={15}/>保存 JSON</button><button className="primary" onClick={() => void copy(support)}><Icon name="copy" size={15}/>复制资料</button></div></Modal>}
    {launchTarget && <Modal title="在准确项目中打开 Claude" wide onClose={() => setLaunchTarget(null)}><div className="modal-body"><LaunchPanel environment={launchTarget.environment} hostAlias={launchTarget.hostAlias} proxyUrl={launchTarget.proxyUrl}/></div></Modal>}
    {flow && <Modal title={flow.receipt ? '执行结果' : flow.uncertain ? '结果待核对' : '确认这份计划'} wide onClose={() => { if (busy !== 'execute') { setFlow(null); setError(''); } }}><div className="plan-target"><Icon name="terminal" size={21}/><div><strong>{flow.environment.name}</strong><span>{flow.hostAlias ?? label(flow.environment.host)} · {label(flow.environment.surface)}</span></div><span className="small-label">仅此目标</span><code className="approval-root">{flow.environment.root}</code><button className="icon-button" aria-label="复制冻结目标路径" onClick={() => void copy(flow.environment.root)}><Icon name="copy" size={15}/></button></div><div className="modal-body flow-body"><div className="flow-intro"><Clawd small mood={busy === 'execute' ? 'work' : flow.receipt ? flow.receipt.status === 'completed' ? 'done' : 'care' : 'plan'}/><div><span className="eyebrow">{flow.receipt ? 'the actual result' : 'take a look together'}</span><h3 className="flow-title">{flow.receipt?.title ?? flow.plan?.title}</h3></div></div>{error && <RequestFailure error={error}/>}
      {(flow.receipt?.service ?? flow.plan?.service) && <ServiceEvidence service={(flow.receipt?.service ?? flow.plan?.service)!}/>}{flow.receipt ? <><TaskOutcome receipt={flow.receipt}/><p className="small-print">记录时间 · {formatDate(flow.receipt.created_at)}</p><div className="steps">{flow.receipt.steps.map((step, index) => <div className="step" key={step.id}><span className="step-number">{index + 1}</span><div><strong>{step.label}</strong><p>{step.message}</p></div><Status value={step.status}/></div>)}</div>{flow.receipt.error && <Notice tone="error"><strong>{flow.receipt.error.message}</strong><p><code>{flow.receipt.error.code}</code> · {flow.receipt.error.phase}</p>{flow.receipt.error.uncertain_side_effects && <p>执行中步骤或写后核验尚未确认；先核对原任务和已产生的内容。</p>}{flow.receipt.error.recovery && <p>{flow.receipt.error.recovery}</p>}</Notice>}<Warnings items={flow.receipt.warnings}/>{flow.receipt.settings_recovery && <Notice tone={flow.receipt.settings_recovery.state === 'written' ? 'neutral' : 'warning'}><strong>配置写入核对</strong><p>{flow.receipt.settings_recovery.message}</p>{flow.receipt.restorable && <p>可以预览恢复仍属于这次任务的字段；恢复需要独立批准。</p>}</Notice>}{!!flow.receipt.next_steps?.length && !flow.receipt.task_result?.next_actions.length && <section className="receipt-next"><h4>接下来</h4><ul>{flow.receipt.next_steps.map((step, index) => <li key={index}>{step}</li>)}</ul></section>}<ExecutionEvidence execution={flow.receipt.execution}/>{flow.receipt.policy && <PolicyEvidence policy={flow.receipt.policy} projected/>}{flow.receipt.local_cleanup && <div className="fact-row"><span>本地清理</span><Status value={flow.receipt.local_cleanup}/></div>}{flow.receipt.remote_revocation && <div className="fact-row"><span>服务端撤销</span><Status value={flow.receipt.remote_revocation}/></div>}{flow.receipt.outcome === 'preserved' && <Notice>工作保全已完成。旧环境与旧登录保留；接下来可选择新环境的保护方案，再正常登录。已有 service 仍绑定原环境，需要单独核对其启动配置。</Notice>}{flow.receipt.migration_probe && flow.receipt.migration_probe.status !== 'removed' && <><div className="fact-row"><span>路径检查临时目录</span><Path value={flow.receipt.migration_probe.path}/></div><Notice tone="warning">按原任务核对这份检查目录。检查只使用空文件；中断后不自动删除可能的额外内容，不重复提交。</Notice></>}{flow.receipt.new_root && <div className="fact-row"><span>{flow.receipt.steps.some(step => step.id === 'create' && step.status === 'completed') ? '新配置目录' : '新配置目录（待核对）'}</span><Path value={flow.receipt.new_root}/></div>}{flow.receipt.state_archive_path && <div className="fact-row"><span>{flow.receipt.steps.some(step => step.id === 'state_backup' && step.status === 'completed') ? '状态备份' : '状态备份（待核对）'}</span><Path value={flow.receipt.state_archive_path}/></div>}{flow.receipt.archive_path && <div className="fact-row"><span>{hasConfirmedWorkArchive(flow.receipt) ? '工作归档' : '工作归档（待核对）'}</span><Path value={flow.receipt.archive_path}/></div>}<div className="receipt-id"><span>任务 ID</span><code>{flow.receipt.id}</code><button className="icon-button" aria-label="复制任务 ID" onClick={() => void copy(flow.receipt!.id)}><Icon name="copy" size={14}/></button></div>{flow.hostAlias && <Notice>打开 Claude 会在 Terminal 连接此主机，使用这个环境的配置目录。会话随 SSH 连接结束；本机网络通道不会覆盖远端。</Notice>}{!flow.receipt.restorable && <p className="muted">此任务没有可用的配置恢复动作。保留项与未完成项以各步骤结果为准。</p>}</> : flow.plan && <>{flow.hostAlias && <Notice>远端会先持久接收，再执行这份任务。断线后能否继续取决于主机现有条件；回执会记录实际托管方式。连接中断时只查询原任务，不再次提交。</Notice>}<Warnings items={flow.plan.warnings}/><PlanReview plan={flow.plan}/>{flow.plan.archive_passphrase_required && <section className="archive-password"><h4>保护工作归档</h4><p>{flow.initialPassphrase ? '迁入时需再次使用归档口令。口令仅临时交给目标执行器，不会写入草案或任务记录。' : <>本次将加密归档 {flow.plan.file_count ?? '所选'} 个文件。设置至少 12 个字符的口令并自行妥善保存；Lintel 不保存口令。之后读取归档需要此口令。</>}</p><div className="password-fields"><label className="field">归档口令<input type="password" autoComplete="new-password" minLength={12} value={archivePassphrase} onChange={event => setArchivePassphrase(event.target.value)}/></label><label className="field">再次输入口令<input type="password" autoComplete="new-password" value={archiveConfirmation} onChange={event => setArchiveConfirmation(event.target.value)}/></label></div>{archiveConfirmation && archiveConfirmation !== archivePassphrase && <p className="password-error">两次输入的口令不一致。</p>}</section>}{flow.plan.policy && <PolicyEvidence policy={flow.plan.policy} projected/>}<section className="plan-steps"><h4>实际步骤</h4>{flow.plan.actions.map(action => <div className="action-description" key={action.id}><span>{action.label}</span><span className="small-label">{action.reversible ? '可恢复' : '无自动恢复'}</span></div>)}</section><details className="plan-identity"><summary>目标与计划标识</summary><Path value={flow.environment.root}/><code className="full-path">{flow.plan.id}</code></details>{flow.uncertain && <Notice tone="warning">没有再次执行。请查询这份计划的原任务；未收到结果不代表操作没有发生。</Notice>}</>}
      </div><div className="modal-footer flow-footer"><span>{flow.environment.name}</span><div className="button-row"><button disabled={!!busy} onClick={() => openAgent(flow)}>交给 Agent</button>{flow.receipt ? <><button onClick={() => { setFlow(null); setPage('history'); }}>查看记录</button>{['accepted','executing','verifying','pending','interrupted','needs_reconciliation'].includes(flow.receipt.status) && <button disabled={!!busy} onClick={refreshReceipt}>查询最新结果</button>}{hasConfirmedWorkArchive(flow.receipt) && <button onClick={() => { setArchiveJobId(flow.receipt!.id); setFlow(null); setPage('sessions'); }}>查看工作归档</button>}{flow.receipt.new_environment_id && environments.some(environment => environment.id === flow.receipt!.new_environment_id) && <button onClick={() => {selectEnvironment(flow.receipt!.new_environment_id!);setFlow(null);setPage('policy');}}>为新环境选择保护方案</button>}{flow.receipt.restorable && <button disabled={!!busy} onClick={() => restore(flow.receipt!)}>预览恢复</button>}{flow.receipt.service_restorable && <button disabled={!!busy} onClick={() => resumeService(flow.receipt!)}>预览恢复服务</button>}{flow.receipt.service ? <button className="primary" onClick={() => { setFlow(null); setPage('rebuild'); }}>返回清理与重建</button> : flow.receipt.outcome !== 'archived' && flow.environment.status !== 'retired' && <button className="primary" title={!['completed','partially_completed','failed'].includes(flow.receipt.status) ? '先查询这份任务的完成结果' : hostAlias ? '在 Terminal 打开此远端环境' : undefined} disabled={!!busy || !['completed','partially_completed','failed'].includes(flow.receipt.status) || !(flow.receipt.new_environment_id ? environments.find(env => env.id === flow.receipt!.new_environment_id)?.executable : flow.environment.executable)} onClick={() => { const target = environments.find(env => env.id === flow.receipt?.new_environment_id) ?? flow.environment; launch(target,flow.hostAlias ?? null);setFlow(null); }}>打开 Claude<Icon name="arrow" size={15}/></button>}</> : flow.uncertain ? <><button onClick={() => { setFlow(null); setPage('history'); setError(''); }}>返回记录</button><button className="primary" disabled={!!busy} onClick={reconcile}>查询原任务</button></> : <><button disabled={!!busy} onClick={() => { setFlow(null); setError(''); }}>返回调整</button><button className="primary" disabled={!!busy || !flow.plan?.actions.length || (!!flow.plan?.archive_passphrase_required && (archivePassphrase.length < 12 || archivePassphrase !== archiveConfirmation))} onClick={() => void executePlan()}>{busy === 'execute' ? '正在执行，请稍候…' : '批准并执行'}<Icon name="arrow" size={15}/></button></>}</div></div></Modal>}
  </div></WorkspaceActionsContext.Provider>;
}

function SettingsRows({ settings }: { settings: Inspection['settings'] }) { return <div className="settings-list">{settings.length === 0 ? <p className="padded muted">此环境没有可展示的已识别设置。</p> : settings.map(setting => <details className="setting-row" key={setting.key}><summary><span><strong>{setting.label}</strong><span className="setting-timing">{label(setting.effect_timing)}</span></span><code>{setting.value ?? '未设置'}</code><Status value={setting.status}/><Icon name="chevron" size={13}/></summary><div className="setting-detail"><code>{setting.key}</code><span>来源：{setting.source}</span><span>记录状态：{label(setting.status)} · 生效时机：{label(setting.effect_timing)}</span></div></details>)}</div>; }
function categoryLabel(value: string) { return ({ instructions: '个人指令', memory: '记忆文本', sessions: '会话资料', settings: '设置文件', projects: '项目资料', credentials: '凭据元数据' } as Record<string,string>)[value] ?? value; }
function SelectTarget({ onAdd }: { onAdd: () => void }) { return <div className="empty-state bordered"><Icon name="environments" size={32}/><h2>先选择一个具体环境</h2><p>每份方案绑定其主机和配置目录。</p><button onClick={onAdd}>添加现有环境</button></div>; }

function ThemeSwitch({ theme, onChange }: { theme: Theme; onChange: (theme: Theme) => void }) { return <div className="theme-switch" role="group" aria-label="外观主题">{([['light','Day','sun'],['dark','Night','moon'],['system','System','environments']] as const).map(([value,title,icon]) => <button key={value} title={value === 'light' ? '浅色 Day' : value === 'dark' ? '深色 Night' : '跟随系统 System'} aria-label={value === 'light' ? '浅色 Day' : value === 'dark' ? '深色 Night' : '跟随系统 System'} aria-pressed={theme === value} onClick={() => onChange(value)}><Icon name={icon} size={13}/><span>{title}</span></button>)}</div>; }
